// Validate the {action, payload} contract and resolve the target url.
//
// Each action maps to a full url in its own env var. Nothing here assumes a
// base path or a route shape, so pointing an action at a Zapier catch hook
// instead of a REST endpoint is a config change, not a workflow change.
const URL_ENV = {
  inbound_routing:      'SALESGOD_URL_INBOUND_ROUTING',
  cross_channel_event:  'SALESGOD_URL_CROSS_CHANNEL_EVENT',
  fallback_sms:         'SALESGOD_URL_FALLBACK_SMS',
};

// Callers name the contact write differently; treat them as one action rather
// than forcing every caller to know the canonical name.
const ALIASES = { upsert: 'inbound_routing', upsert_contact: 'inbound_routing' };

const raw = $json ?? {};

// Accept the nested contract {action, payload} and the flattened
// {action, ...fields} shape, so a caller that spreads its fields still works.
let action = String(raw.action || '').trim();
let payload = raw.payload;
if (payload === undefined || payload === null) {
  const { action: _drop, ...rest } = raw;
  payload = rest;
}

if (!action) {
  // Name what actually arrived - an empty object here almost always means the
  // calling Execute Workflow node has a 'defineBelow' input mapping that
  // replaced the item instead of passing it through.
  const keys = Object.keys(raw);
  throw new Error(
    'SalesGod Adapter called without an "action". Expected { action, payload }. ' +
    `Received keys: [${keys.join(', ') || 'none - empty item'}]. ` +
    'If empty, clear the "Workflow Inputs" mapping on the calling ' +
    'Execute Workflow node so the item passes through.'
  );
}

action = ALIASES[action] || action;

if (!URL_ENV[action]) {
  throw new Error(
    `SalesGod Adapter received unknown action "${action}". ` +
    `Known actions: ${Object.keys(URL_ENV).join(', ')} ` +
    `(aliases: ${Object.keys(ALIASES).join(', ')}).`
  );
}

let targetUrl = '';
try { targetUrl = String($env[URL_ENV[action]] || '').trim(); } catch (e) { targetUrl = ''; }

// Callers supply a stable dedupe key; fall back to something deterministic so
// the adapter is still idempotent if they forget.
const dedupeKey = payload.dedupe_key
  || `salesgod:${action}:${payload.email || payload.phone || payload.event_id || 'unknown'}`;

// Surface how much SalesGod has to work with. Endpoint-agnostic: the
// receiving side can branch on this without us knowing its schema.
const VECTORS = ['company_domain', 'company_name', 'job_title', 'linkedin_url', 'email'];
const present = VECTORS.filter(k => payload[k]);

return {
  json: {
    enrichment_ready: !payload.phone && present.length > 0,
    enrichment_vectors: present,
    action,
    payload,
    dedupe_key: dedupeKey,
    target_url: targetUrl,
    is_live: targetUrl.length > 0,
    url_env_var: URL_ENV[action],
  },
};

