parameters.jsCode:
// Single response shape for callers, whether this ran live, stubbed, or failed.
// Callers use onError=continueRegularOutput, so a failure must be reported in
// the payload rather than thrown -- a dead SalesGod must not fail an execution
// whose email enrollment already succeeded.
const ctx = $('Validate Request').first().json;

let live = false;
try { live = $('SalesGod: Dispatch').isExecuted; } catch (e) { live = false; }

const j = $json || {};
const errored = Boolean(j.error) || Boolean(j.__isErrorItem);

return {
  json: {
    ok: !errored,
    action: ctx.action,
    mode: live ? 'live' : 'stub',
    dedupe_key: ctx.dedupe_key,
    remote_id: j.id ?? j.contact_id ?? j.data?.id ?? (live ? null : `stub-${ctx.dedupe_key}`),
    error: errored ? (j.error?.message ?? String(j.error ?? 'unknown adapter error')) : null,
    raw: live ? j : null,
  },
};
